#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    const int Z = 100;
    const int N = Z * Z;
    const int M = Z * Z * Z * 3;
    vector<int> px(N), py(N), head(N, -1), to(M), ct(M), w(M), nt(M);
    vector<int> dist(N), visited(N), parent(N), edge_id(N);
    int total_edges = 0;

    auto add_edge = [&](int u, int v, int flow, int cost) {
        to[total_edges] = v; ct[total_edges] = cost; w[total_edges] = flow; nt[total_edges] = head[u]; head[u] = total_edges++;
        to[total_edges] = u; ct[total_edges] = -cost; w[total_edges] = 0; nt[total_edges] = head[v]; head[v] = total_edges++;
    };

    auto initialize = [&]() {
        fill(head.begin(), head.end(), -1);
        total_edges = 0;
    };

    auto spfa = [&](int s, int t) {
        queue<int> q;
        fill(dist.begin(), dist.end(), INT_MAX);
        fill(visited.begin(), visited.end(), 0);
        fill(parent.begin(), parent.end(), -1);
        dist[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            visited[u] = 0;
            for (int i = head[u]; i != -1; i = nt[i]) {
                if (w[i] > 0 && dist[to[i]] > dist[u] + ct[i]) {
                    dist[to[i]] = dist[u] + ct[i];
                    parent[to[i]] = u;
                    edge_id[to[i]] = i;
                    if (!visited[to[i]]) {
                        visited[to[i]] = 1;
                        q.push(to[i]);
                    }
                }
            }
        }
        return dist[t] < INT_MAX;
    };

    auto max_flow = [&](int s, int t) {
        int total_flow = 0, total_cost = 0;
        while (spfa(s, t)) {
            int flow = INT_MAX;
            for (int i = t; i != s; i = parent[i]) {
                flow = min(flow, w[edge_id[i]]);
            }
            for (int i = t; i != s; i = parent[i]) {
                w[edge_id[i]] -= flow;
                w[edge_id[i] ^ 1] += flow;
            }
            total_cost += dist[t] * flow;
            total_flow += flow;
        }
        return total_cost;
    };

    int s = 0, t = n * 100 + 1;
    initialize();
    for (int i = 1; i <= 100; ++i)
        add_edge(i, t, 100, 0);
    for (int i = 1, v; i <= k; ++i) {
        cin >> v;
        add_edge(s, (v - 1) * 100 + 1, 1, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            add_edge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
        }
    }
    for (int i = 1, u, v; i <= m; ++i) {
        cin >> u >> v;
        for (int j = 1; j < 100; ++j) {
            int idx = (u - 1) * 100 + j;
            int idy = (v - 1) * 100 + j + 1;
            for (int k = 1; k <= 50; ++k) {
                add_edge(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
        for (int j = 1; j < 100; ++j) {
            int idx = (v - 1) * 100 + j;
            int idy = (u - 1) * 100 + j + 1;
            for (int k = 1; k <= 50; ++k) {
                add_edge(idx, idy, 1, c + (k * k - (k - 1) * (k - 1)) * d);
            }
        }
    }
    cout << max_flow(s, t) << "\n";
    return 0;
}
